UPDATE media
SET is_favorite = #{isFavorite}, updated_at = NOW()
WHERE id = #{id}

UPDATE media
SET is_deleted = #{isDeleted}, deleted_at = #{deletedAt}, updated_at = NOW()
WHERE id = #{id}

UPDATE media
SET is_deleted = FALSE, deleted_at = NULL, updated_at = NOW()
WHERE id = #{id}

UPDATE media
SET album_id = #{albumId}, updated_at = NOW()
WHERE id = #{id}
